Patient Portal.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Patient Portal container

Container_Boundary(patient_portal, "Patient Portal") {
    Component(React_SPA, "React SPA", "React, WCAG 2.1 AA, Multi-language support", "Powers the frontend UI enabling patients to manage appointments, view EMR, and handle billing.")
    Component(Edge_CDN, "Edge CDN", "Content Delivery Network", "Loads static UI assets for the Patient Portal.")
}

Rel(React_SPA, Edge_CDN, "Loads static UI assets", "HTTPS")

@enduml

Clinical Core.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Clinical Core container

Container_Boundary(clinical_core, "Clinical Core") {
    Component(EMR, "EMR", "HL7 FHIR, Java/Spring", "Handles electronic medical records and clinical workflows.")
    Component(Scheduling, "Scheduling", "Java/Spring", "Manages patient appointments and scheduling.")
    Component(Billing_Reconciliation, "Billing Reconciliation", "Java/Spring, Dead-Letter Queues", "Processes billing reconciliation and communicates with insurance payers.")
}

Rel(EMR, Scheduling, "Coordinates patient appointments with medical records")
Rel(EMR, Billing_Reconciliation, "Triggers billing events for clinical services")
@enduml

Notification & Reminder Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Notification & Reminder Container container

Container_Boundary(notification_reminder_container, "Notification & Reminder Container") {
    Component(Notification_Dispatcher, "Notification Dispatcher", "Node.js / TLS 1.3 Client", "Dispatches external notifications securely via TLS 1.3 with client certificate pinning.")
    Component(Reminder_Scheduler, "Reminder Scheduler", "Python / Celery", "Manages and triggers scheduled patient appointment reminders and alerts.")
}

Rel(Reminder_Scheduler, Notification_Dispatcher, "Triggers message dispatch")

@enduml
